import '../../domain/academic/academic_models.dart';
import 'academic_knowledge_unit_catalog.dart';

/// Subject-aware lesson blueprints for the global TOFAN academic library.
/// These are original instructional structures, not copied university text.
class AcademicLessonSpec {
  const AcademicLessonSpec({
    required this.title,
    required this.topic,
    required this.definition,
    required this.content,
    required this.terms,
    required this.examples,
    required this.applications,
  });

  final String title;
  final String topic;
  final String definition;
  final String content;
  final List<String> terms;
  final List<String> examples;
  final List<String> applications;
}

class AcademicCourseLessonBlueprints {
  const AcademicCourseLessonBlueprints._();

  static List<AcademicLessonSpec> forCourse(String courseName, List<String> knowledgeUnitIds) {
    final n = courseName.toLowerCase();

    final global = _globalProjectBlueprint(courseName);
    if (global != null) return global;

    if (n.contains('python') || n.contains('البرمجة 1') || n == 'البرمجة') {
      return _python(courseName);
    }
    if (n.contains('برمجة') || n.contains('البرمجة الكائنية') || n.contains('برمجة منخفضة')) return _programming(courseName);
    if (n.contains('إدارة المشاريع')) return _projectManagement(courseName);
    if (n.contains('تصميم') || n.contains('وسائط تفاعلية')) return _design(courseName);
    if (n.contains('معالجة الإشارة')) return _signal(courseName);
    if (n.contains('خوارز') || n.contains('هياكل البيانات')) return _algorithms(courseName);
    if (n.contains('قواعد البيانات') || n.contains('نمذجة البيانات') || n.contains('هندسة البيانات')) return _data(courseName);
    if (n.contains('تعلم الآلة')) return _ml(courseName);
    if (n.contains('ذكاء اصطناعي') || n.contains('الذكاء الاصطناعي') || n.contains('ai')) return _ai(courseName);
    if (n == 'علم البيانات') return _analytics(courseName);
    if (n.contains('شبك')) return _network(courseName);
    if (n.contains('نظم التشغيل') || n.contains('أنظمة التشغيل')) return _os(courseName);
    if (n.contains('أمن') || n.contains('تشفير') || n.contains('cyber') ||
        n.contains('اختبار الاختراق') || n.contains('الهجوم والدفاع') ||
        n.contains('تقييم الاختراق') || n.contains('الفريق الأحمر')) {
      return _security(courseName);
    }
    if (n.contains('مترجمات') || n.contains('compiler')) return _compilers(courseName);
    if (n.contains('أساسيات الحوسبة') || n.contains('موضوعات متقدمة')) return _systemsFundamentals(courseName);
    if (n.contains('هندسة البرمجيات') || n.contains('اختبار البرمجيات') || n.contains('devops') || n.contains('إدارة الإصدارات')) return _software(courseName);
    if (n.contains('ويب')) return _web(courseName);
    if (n.contains('معمار') || n.contains('منطق رقمي') || n.contains('معالجات') || n.contains('برمجة منخفضة')) return _architecture(courseName);
    if (n.contains('رسوميات') || n.contains('واقع افتراضي') || n.contains('واقع معزز')) return _graphics(courseName);
    if (n.contains('تفاعل') || n.contains('تجربة المستخدم') || n.contains('قابلية الاستخدام') || n.contains('hci')) return _hci(courseName);
    if (n.contains('إحصاء') || n.contains('احتمال')) return _statistics(courseName);
    if (n.contains('رياضيات') || n.contains('منطق')) return _math(courseName);
    if (n.contains('سحاب')) return _cloud(courseName);
    if (n.contains('مضمن') || n.contains('إنترنت الأشياء') || n.contains('زمنية')) return _embedded(courseName);
    if (n.contains('ذكاء الأعمال') || n.contains('تحليل البيانات') || n.contains('تنقيب البيانات') || n.contains('تصوير البيانات') || n.contains('السلاسل الزمنية') || n.contains('معالجة اللغة')) return _analytics(courseName);
    if (n.contains('إدارة خدمات') || n.contains('دعم المستخدم') || n.contains('استمرارية الأعمال') || n.contains('تدقيق الأنظمة') || n.contains('إدارة البنية التحتية') || n.contains('افتراضية')) return _itOperations(courseName);
    if (n.contains('حوكمة') || n.contains('التحول الرقمي') || n.contains('نظم المؤسسات') || n.contains('تخطيط موارد المؤسسة') || n.contains('إدارة الأعمال') || n.contains('إدارة العمليات')) return _informationSystems(courseName);
    if (n.contains('منهجية البحث') || n.contains('ندوة')) return _research(courseName);
    if (n.contains('مشروع التخرج')) return _capstone(courseName);
    if (n.contains('أخلاقيات') || n.contains('المهنة') || n.contains('المجتمع')) return _ethics(courseName);

    // Existing domain families are reused for closely related courses so that
    // generated global curricula do not silently fall back to generic lessons.
    if (n.contains('الأنظمة الموزعة') || n.contains('الحوسبة المتوازية')) return _systemsFundamentals(courseName);
    if (n.contains('تحليل المتطلبات') || n.contains('ضمان الجودة') || n.contains('تطوير التطبيقات')) return _software(courseName);
    if (n.contains('أساسيات تقنية المعلومات') || n.contains('إدارة الأنظمة')) return _itOperations(courseName);
    if (n.contains('مقدمة نظم المعلومات') || n.contains('تحليل النظم') || n.contains('نظم دعم القرار') || n.contains('إدارة الخدمات')) return _informationSystems(courseName);
    if (n.contains('معالجة البيانات الضخمة') || n.contains('التجارب وتحليلها') || n.contains('هندسة منصات البيانات')) return _analytics(courseName);
    if (n.contains('الذكاء الاصطناعي التطبيقي')) return _ai(courseName);
    if (n.contains('الاستجابة للحوادث') || n.contains('تحليل البرمجيات الخبيثة') || n.contains('التحقيق الجنائي الرقمي')) return _security(courseName);
    if (n.contains('النمذجة ثلاثية الأبعاد') || n.contains('الواقع الافتراضي') || n.contains('الرؤية الحاسوبية') || n.contains('الواقع المعزز')) return _graphics(courseName);
    return _domain(courseName, knowledgeUnitIds);
  }

  static AcademicLessonSpec _s(String title, String topic, String definition, String content, List<String> terms, List<String> examples, List<String> applications) =>
      AcademicLessonSpec(title: title, topic: topic, definition: definition, content: content, terms: terms, examples: examples, applications: applications);

