    _s('بيئة Python وبنية البرنامج', 'تنفيذ البرنامج وتسلسل التعليمات', 'Python لغة برمجة عالية المستوى تستخدم للتعبير عن خوارزميات قابلة للتنفيذ.',
      'يتعلم الطالب كيف يقرأ ملف Python من أعلى إلى أسفل، وكيف ترتبط التعليمات بالمدخلات والمخرجات. يبدأ العمل بتحديد المشكلة ثم كتابة خطوات الحل قبل تحويلها إلى صياغة برمجية. يجب التفريق بين الخطأ النحوي والخطأ المنطقي والخطأ الناتج عن البيانات.',
      ['Python','مفسر','تعليمة','مخرجات','خطأ نحوي'], ['برنامج يطبع نتيجة ثابتة','تتبع تنفيذ ثلاث تعليمات'], ['الأتمتة','أدوات سطر الأوامر']),
    _s('المتغيرات والأنواع والتحويل', 'تمثيل البيانات داخل البرنامج', 'المتغير اسم مرتبط بقيمة، ونوع البيانات يحدد طبيعة القيمة والعمليات الملائمة لها.',
      'يفحص الطالب str وint وfloat وbool ويقارن بين التمثيل النصي والعددي. يتعلم أن input يعيد نصًا، وأن التحويل يجب أن يكون مقصودًا ومتحققًا منه. ثم يختبر تأثير تغيير النوع على العمليات والنتيجة.',
      ['str','int','float','bool','type','تحويل'], ['int(input(...))','فحص type قبل الحساب'], ['برامج البيانات الشخصية','الحاسبات']),
    _s('التعبيرات والعمليات ودفق التنفيذ', 'الحساب وترتيب التنفيذ', 'التعبير البرمجي تركيب ينتج قيمة بعد تطبيق قواعد اللغة وترتيب العمليات.',
      'يبني الطالب تعبيرات حسابية ونصية ويحلل أولوية العمليات. يطبق + و- و* و/ و// و% و**، ثم يقارن النتيجة المتوقعة بالمخرجات الفعلية. التركيز على تفسير سبب النتيجة، لا حفظ العامل منفردًا.',
      ['تعبير','أولوية','قسمة صحيحة','باقي القسمة','أس'], ['حساب متوسط','استخراج باقي القسمة'], ['الحسابات التعليمية','معالجة المدخلات']),
    _s('الشروط والتكرار', 'التحكم في مسار التنفيذ', 'جمل التحكم تسمح للبرنامج باختيار مسار أو تكرار مجموعة تعليمات وفق شرط.',
      'يحول الطالب قواعد المشكلة إلى if وelif وelse وحلقات. يحدد شرط البداية والنهاية، ويتحقق من الحالات الحدية لتجنب الحلقة غير المنتهية أو فرع لا يمكن الوصول إليه. كل قرار يجب أن يرتبط بمتطلب واضح.',
