    _s('الدوال وهياكل البيانات الأساسية', 'التجريد وإعادة الاستخدام', 'الدالة كتلة قابلة لإعادة الاستخدام تستقبل مدخلات اختيارية وتعيد نتيجة أو تنفذ أثرًا محددًا.',
      'ينظم الطالب البرنامج إلى دوال ذات مسؤوليات واضحة، ثم يستخدم list وtuple وdict وset لتمثيل مجموعات البيانات. يختار البنية بناء على العمليات المطلوبة، ويختبر كل دالة بمدخلات عادية وحدية.',
      ['دالة','معامل','return','list','dict','set'], ['دالة لحساب المتوسط','قاموس لبيانات طالب'], ['تنظيم المشاريع الصغيرة','معالجة السجلات']),
    _s('مشروع Python واختبار الأخطاء', 'تحويل المتطلبات إلى برنامج قابل للتحقق', 'المشروع البرمجي حل متكامل يربط المتطلبات بالكود والاختبارات والتوثيق.',
