    final topics = profiles[courseName];
    if (topics == null) return null;
    final stages = ['تحليل المتطلبات والنطاق','تصميم النموذج والمعمارية','تنفيذ المكوّن الأساسي','اختبار الحالات والقيود','تحليل النتائج وتحسين الحل','دمج المكونات وتوثيق المشروع'];
    return List<AcademicLessonSpec>.generate(6, (index) {
      final topic = topics[index];
      final stage = stages[index];
      return AcademicLessonSpec(
        title: topic,
        topic: topic,
        definition: 'مفهوم «$topic» هو جزء تخصصي من مقرر «$courseName» يستخدم للوصول إلى قدرة عملية قابلة للإثبات.',
        content: 'يدرس الطالب «$topic» من منظور «$courseName»، ثم يربطه بمرحلة «$stage». يبدأ العمل بتحديد المدخلات والافتراضات والقيود، ثم اختيار النموذج أو الأداة المناسبة، وتنفيذ خطوة قابلة للملاحظة، وقياس النتيجة، وتحليل الأخطاء قبل الانتقال إلى المرحلة التالية. يجب أن يكون الناتج قابلاً لإعادة الاختبار والتوثيق، وأن يوضح الطالب سبب اختيار الحل وحدوده.',
        terms: [courseName, topic, 'متطلبات', 'اختبار', 'دليل', 'قيود'],
        examples: ['حالة عملية مرتبطة بـ$topic', 'مقارنة بديلين في $courseName'],
        applications: ['تطبيق $topic في مشروع $courseName', 'توثيق دليل قابل للمراجعة'],
      );
    });
  }

  static List<AcademicLessonSpec> _domain(String c, List<String> unitIds) {
    final units = unitIds.map(AcademicKnowledgeUnitCatalog.byId).whereType<AcademicKnowledgeUnit>().toList();
    final focus = units.isEmpty ? 'المفاهيم الأساسية في $c' : units.first.arabicName;
    return List<AcademicLessonSpec>.generate(6, (i) {
      final stage = ['الأساس المفاهيمي','البنية والمكونات','التطبيق الموجه','التحليل والمقارنة','التصميم والتحقق','التكامل والمشروع'][i];
      return _s(
        '$stage في $c',
        '$focus — $stage',
        'هذا الدرس يعرّف «$focus» داخل مقرر «$c» ويربط المعرفة بالتطبيق والتحقق.',
        'يدرس الطالب «$focus» داخل سياق «$c»، ثم يحدد المكونات والعلاقات والافتراضات والقيود. في التطبيق يحول المفهوم إلى حالة قابلة للملاحظة، ويقارن البدائل ويختبر النتيجة. في المرحلة الأخيرة يربط أكثر من مفهوم في حل صغير موثق، مع فصل الدليل عن الاستنتاج وتحديد ما يحتاج إلى تحقق إضافي.',
        [focus, 'تحليل', 'تطبيق', 'تحقق', 'قيود'],
        ['حالة تطبيقية في $c', 'مقارنة بديلين مرتبطين بـ$focus'],
        ['التطبيق العملي في $c', 'مشروع مصغر مرتبط بوحدات المعرفة'],
      );
    });
  }
}
